//
// This module is the fixed external boundary for the experimental world. The
// protocol deliberately hides the internal entity and rule module structure.

import { WorldProtocol, OperationResult } from "../../schema";
import { WorldState, createInitialWorld } from "./world";
import { advanceVok1, advanceVok2 } from "./vok/rules";
import { advanceZef1, advanceZef2 } from "./zef/rules";
import { advanceTal1 } from "./tal/rules";
import { advanceOsk1 } from "./osk/rules";
import {
  advanceFen1,
  advanceFen2,
  recoverFen,
} from "./fen/rules";

const operations: Record<string, (world: WorldState) => WorldState> = {
  advanceVok1,
  advanceVok2,
  advanceZef1,
  advanceZef2,
  advanceTal1,
  advanceOsk1,
  advanceFen1,
  advanceFen2,
  recoverFen,
};

function operationError(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return createInitialWorld();
  },

  applyOperation(
    state: WorldState,
    operationDisplayName: string,
  ): OperationResult {
    const operation = operations[operationDisplayName];
    if (typeof operation !== "function") {
      return {
        success: false,
        error: `Unknown operation: ${operationDisplayName}`,
      };
    }

    try {
      return {
        success: true,
        newState: operation(state),
      };
    } catch (error) {
      return {
        success: false,
        error: operationError(error),
      };
    }
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    switch (entityDisplayName.toLowerCase()) {
      case "vok":
        return state.vok;
      case "zef":
        return state.zef;
      case "tal":
        return state.tal;
      case "fen":
        return state.fen;
      case "osk":
        return state.osk;
      default:
        throw new Error(`Unknown entity: ${entityDisplayName}`);
    }
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return {
      Vok: state.vok,
      Zef: state.zef,
      Tal: state.tal,
      Fen: state.fen,
      Osk: state.osk,
    };
  },
};
